CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE TABLE "Experiences" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Company" character varying(200) NOT NULL,
    "Position" character varying(200) NOT NULL,
    "Location" character varying(200),
    "StartDate" date NOT NULL,
    "EndDate" date,
    "IsCurrent" boolean NOT NULL,
    "Description" text,
    "DisplayOrder" integer NOT NULL,
    "IsPublished" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_Experiences" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_Experiences_CurrentHasNoEndDate" CHECK ("IsCurrent" = FALSE OR "EndDate" IS NULL),
    CONSTRAINT "CK_Experiences_EndDateNotBeforeStartDate" CHECK ("EndDate" IS NULL OR "EndDate" >= "StartDate")
);

CREATE TABLE "Projects" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" character varying(200) NOT NULL,
    "Slug" character varying(200) NOT NULL,
    "ShortDescription" character varying(500) NOT NULL,
    "Description" text,
    "ImageUrl" character varying(1000),
    "RepositoryUrl" character varying(1000),
    "LiveUrl" character varying(1000),
    "DisplayOrder" integer NOT NULL,
    "IsFeatured" boolean NOT NULL DEFAULT FALSE,
    "IsPublished" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_Projects" PRIMARY KEY ("Id")
);

CREATE TABLE "Roles" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "Priority" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_Roles" PRIMARY KEY ("Id")
);

CREATE TABLE "Technologies" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(100) NOT NULL,
    "Category" character varying(100) NOT NULL,
    "Icon" character varying(100),
    "DisplayOrder" integer NOT NULL,
    "IsVisible" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_Technologies" PRIMARY KEY ("Id")
);

CREATE TABLE "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Email" character varying(255) NOT NULL,
    "LastName" character varying(200) NOT NULL,
    "FirstName" character varying(200) NOT NULL,
    "ProfilePictureUrl" character varying(1000),
    "GoogleSubject" character varying(255),
    "SecurityStamp" uuid NOT NULL,
    "IsLocked" boolean NOT NULL DEFAULT FALSE,
    "LastLoginAt" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);

CREATE TABLE "ProjectTechnologies" (
    "ProjectId" integer NOT NULL,
    "TechnologyId" integer NOT NULL,
    CONSTRAINT "PK_ProjectTechnologies" PRIMARY KEY ("ProjectId", "TechnologyId"),
    CONSTRAINT "FK_ProjectTechnologies_Projects_ProjectId" FOREIGN KEY ("ProjectId") REFERENCES "Projects" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_ProjectTechnologies_Technologies_TechnologyId" FOREIGN KEY ("TechnologyId") REFERENCES "Technologies" ("Id") ON DELETE CASCADE
);

CREATE TABLE "Consents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "Type" integer NOT NULL,
    "PolicyVersion" character varying(50) NOT NULL,
    "AcceptedAt" timestamp with time zone NOT NULL,
    "RevokedAt" timestamp with time zone,
    CONSTRAINT "PK_Consents" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Consents_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id")
);

CREATE TABLE "PageContents" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Key" character varying(100) NOT NULL,
    "Title" character varying(250),
    "Subtitle" character varying(500),
    "Content" text,
    "IsPublished" boolean NOT NULL DEFAULT TRUE,
    "UpdatedByUserId" integer,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_PageContents" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PageContents_Users_UpdatedByUserId" FOREIGN KEY ("UpdatedByUserId") REFERENCES "Users" ("Id") ON DELETE SET NULL
);

CREATE TABLE "UserRoles" (
    "UserId" integer NOT NULL,
    "RoleId" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT (CURRENT_TIMESTAMP),
    CONSTRAINT "PK_UserRoles" PRIMARY KEY ("RoleId", "UserId"),
    CONSTRAINT "FK_UserRoles_Roles_RoleId" FOREIGN KEY ("RoleId") REFERENCES "Roles" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_UserRoles_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

CREATE TABLE "ContactMessages" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "ConsentId" integer NOT NULL,
    "Subject" character varying(250) NOT NULL,
    "Message" character varying(4000) NOT NULL,
    "Status" integer NOT NULL DEFAULT 1,
    "CreatedAt" timestamp with time zone NOT NULL,
    "ReadAt" timestamp with time zone,
    "ResolvedAt" timestamp with time zone,
    CONSTRAINT "PK_ContactMessages" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ContactMessages_Consents_ConsentId" FOREIGN KEY ("ConsentId") REFERENCES "Consents" ("Id"),
    CONSTRAINT "FK_ContactMessages_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id")
);

