CREATE INDEX "IX_Consents_Type_PolicyVersion" ON "Consents" ("Type", "PolicyVersion");

CREATE INDEX "IX_Consents_UserId_Type_AcceptedAt" ON "Consents" ("UserId", "Type", "AcceptedAt");

CREATE UNIQUE INDEX "IX_ContactMessages_ConsentId" ON "ContactMessages" ("ConsentId");

CREATE INDEX "IX_ContactMessages_Status_CreatedAt" ON "ContactMessages" ("Status", "CreatedAt");

CREATE INDEX "IX_ContactMessages_UserId_CreatedAt" ON "ContactMessages" ("UserId", "CreatedAt");

CREATE INDEX "IX_Experiences_IsPublished_DisplayOrder" ON "Experiences" ("IsPublished", "DisplayOrder");

CREATE UNIQUE INDEX "IX_PageContents_Key" ON "PageContents" ("Key");

CREATE INDEX "IX_PageContents_UpdatedByUserId" ON "PageContents" ("UpdatedByUserId");

CREATE INDEX "IX_Projects_IsPublished_DisplayOrder" ON "Projects" ("IsPublished", "DisplayOrder");

CREATE UNIQUE INDEX "IX_Projects_Slug" ON "Projects" ("Slug");

CREATE INDEX "IX_ProjectTechnologies_TechnologyId" ON "ProjectTechnologies" ("TechnologyId");

CREATE UNIQUE INDEX "IX_Roles_Name" ON "Roles" ("Name");

CREATE INDEX "IX_Technologies_IsVisible_DisplayOrder" ON "Technologies" ("IsVisible", "DisplayOrder");

CREATE UNIQUE INDEX "IX_Technologies_Name" ON "Technologies" ("Name");

CREATE INDEX "IX_UserRoles_UserId" ON "UserRoles" ("UserId");

CREATE UNIQUE INDEX "IX_Users_Email" ON "Users" ("Email");

CREATE UNIQUE INDEX "IX_Users_GoogleSubject" ON "Users" ("GoogleSubject");

SELECT setval(
    pg_get_serial_sequence('"Roles"', 'Id'),
    GREATEST(
        (SELECT MAX("Id") FROM "Roles") + 1,
        nextval(pg_get_serial_sequence('"Roles"', 'Id'))),
    false);

